mapper.select:
SELECT DISTINCT kb.* FROM knowledge_base kb
LEFT JOIN knowledge_base_dept kbd ON kb.id = kbd.knowledge_base_id
LEFT JOIN knowledge_security_label ksl ON kb.security_label_id = ksl.id
WHERE kb.del_flag = 0
AND (
    kb.user_id = #{userId}
    OR (
        kbd.dept_id = #{deptId}
        AND (ksl.label_level IS NULL OR ksl.label_level <= (
            SELECT MAX(ksl2.label_level)
            FROM sys_user_role sur
            JOIN sys_role sr ON sur.role_id = sr.id
            JOIN knowledge_security_label ksl2 ON sr.security_label_id = ksl2.id
            WHERE sur.user_id = #{userId}
        ))
    )
)
ORDER BY kb.create_time DESC
